import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 15 章 自动化工作流：让任务自己跑（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第15章 自动化工作流：让任务自己跑（易懂版）.md","filePath":"easy/第15章 自动化工作流：让任务自己跑（易懂版）.md"}'),l={name:"easy/第15章 自动化工作流：让任务自己跑（易懂版）.md"};function s(n,t,i,u,h,d){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-15-章-自动化工作流-让任务自己跑-易懂版" tabindex="-1">第 15 章 自动化工作流：让任务自己跑（易懂版） <a class="header-anchor" href="#第-15-章-自动化工作流-让任务自己跑-易懂版" aria-label="Permalink to &quot;第 15 章 自动化工作流：让任务自己跑（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 15 章 自动化工作流：让任务自己跑（完整版）](../../bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 15 章 自动化工作流：让任务自己跑.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>把&quot;每周一早上要做的 5 件事&quot;打包成一条流水线——以后一键执行，不用每次从头交代。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>咖啡店的&quot;开店流程&quot;是固定的：开灯 → 摆桌椅 → 烧水 → 磨豆 → 试做一杯。写下来照着做，每天开店又快又稳。</p><p>自动化工作流就是<strong>把这种固定流程固化下来</strong>：输入固定 → 步骤固定 → 输出固定。</p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>识别重复</strong>：找&quot;每周/每月都要做、步骤一样&quot;的事——这就是工作流的候选。</li><li><strong>固化步骤</strong>：把流程写成&quot;第 1 步做什么 → 第 2 步做什么&quot;，存成模板/指令集，随时复用。</li><li><strong>一键执行</strong>：以后只说&quot;跑一下周报流程&quot;，它就按步骤走完。</li></ol><h2 id="适合固化的典型流程" tabindex="-1">适合固化的典型流程 <a class="header-anchor" href="#适合固化的典型流程" aria-label="Permalink to &quot;适合固化的典型流程&quot;">​</a></h2><ul><li>📋 <strong>周报流水线</strong>：收集本周产出 → 整理 → 套模板 → 生成周报；</li><li>📊 <strong>数据刷新</strong>：读新数据 → 清洗 → 更新图表 → 发新版；</li><li>🗂️ <strong>归档流程</strong>：月底把文件按规则归档、重命名、生成清单。</li></ul><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;帮我建一个周报工作流：①读 <code>本周记录</code> 文件夹 → ②按 成果/问题/计划 整理 → ③套用周报模板 → ④输出到 <code>交付</code>。以后说&#39;跑周报&#39;就执行。&quot;</p><p><strong>你会看到</strong>：我把流程固化 → 试跑一遍给你看 → 存好 → 下次一句&quot;跑周报&quot;直接干活。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 流程没跑通就固化——<strong>先手动跑通几次，再自动化</strong>；</li><li>❌ 流程永远不变——<strong>环境和需求变了，记得更新流程</strong>；</li><li>❌ 全自动不检查——<strong>自动化只负责&quot;跑&quot;，不代表&quot;对&quot;，关键环节要验</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>自动化 = 找重复 → 固化成流程 → 一键执行 → 关键环节仍要检查。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>回想你每周重复做的事——<strong>选一件，先手动跑通，再让我固化成工作流。</strong></p><p>👉 [下一章：团队协作，从个人到 AI 团队（易懂版）](第16章 团队协作：从个人到 AI 团队（易懂版）.md)</p>',20)])])}const q=o(l,[["render",s]]);export{_ as __pageData,q as default};
